import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem128 preserva oferta e afiliado',()=>{for(const [id,titulo,expected,link] of [["Ql4iYvaqcH2l6SPpBDsi","Camiseta Dry-fit Preta Caveira Unisex Dark Lab","Camiseta Dry-fit Preta Caveira Unisex Dark Lab","https://produto.mercadolivre.com.br/MLB-3800842215-camiseta-dry-fit-preta-caveira-unisex-dark-lab-_JM?searchVariation=181250232814"],["qN6qOlF1Re6ltU5WRdaE","Caminhão Dinossauro Pista Com 8 Carrinhos Maleta Transporte","Caminhão dinossauro porta-carrinhos — 8 mini carrinhos anunciados","https://www.mercadolivre.com.br/p/MLB77111694?pdp_filters=item_id%3AMLB7399445176"],["QNzmR100ehzO5NSBLhTw","Magnésio Bisglicinato - 60 Cápsulas - Nutrify","Magnésio Bisglicinato - 60 Cápsulas - Nutrify","https://www.mercadolivre.com.br/p/MLB19640094?wid=MLB3905028657"]]){const p={id,titulo,link,linkAfiliado:'https://meli.la/preservar',preco:'preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);assert.equal(x.titulo,expected);for(const k of ['id','link','linkAfiliado','preco'])assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);}});
